const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
require('dotenv').config(); // Load environment variables

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Logging
app.use(morgan('combined'));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Example: Validate numeric parameters
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
      });
    }
  }
  next();
};

// Request timeout middleware
app.use((req, res, next) => {
  res.setTimeout(10000, () => {
    res.status(503).json({ error: 'Request timeout' });
  });
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', validateQueryParams, async (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Validate and sanitize inputs
    const validatedLimit = Math.min(parseInt(limit) || 10, 100);
    const validatedOffset = Math.max(parseInt(offset) || 0, 0);

    // In a real application, this would come from a database
    // For demonstration, using hardcoded data but would normally use environment variables
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(validatedOffset, validatedOffset + validatedLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        total: users.length,
        hasMore: validatedOffset + validatedLimit < users.length,
      },
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : 'Something went wrong'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const errorResponse = {
    error: 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { 
      message: error.message,
      stack: error.stack 
    })
  };

  res.status(error.status || 500).json(errorResponse);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

{
  "name": "secure-express-app",
  "version": "1.0.0",
  "description": "A secure Express.js application with proper error handling and input validation",
  "main": "app-enhanced.js",
  "scripts": {
    "start": "node app-enhanced.js",
    "dev": "nodemon app-enhanced.js",
    "test": "jest"
  },
  "keywords": ["express", "security", "error-handling", "validation"],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "cors": "^2.8.5",
    "morgan": "^1.10.0",
    "dotenv": "^16.3.1"
  },
  "devDependencies": {
    "nodemon": "^3.0.1",
    "jest": "^29.7.0"
  },
  "engines": {
    "node": ">=16.0.0"
  }
}

const { body, query, param, validationResult } = require('express-validator');

// Common validation rules
const commonValidators = {
  email: body('email').isEmail().normalizeEmail(),
  password: body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
  name: body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters'),
  idParam: param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  limitQuery: query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  offsetQuery: query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
};

// Validation error formatter
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }

  next();
};

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  // Sanitize body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
      }
    });
  }

  next();
};

// XSS prevention middleware
const preventXSS = (req, res, next) => {
  // Simple XSS prevention by escaping HTML characters
  const escapeHtml = (unsafe) => {
    return unsafe
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  };

  // Escape all string values in query and body
  const escapeObject = (obj) => {
    if (obj && typeof obj === 'object') {
      Object.keys(obj).forEach(key => {
        if (typeof obj[key] === 'string') {
          obj[key] = escapeHtml(obj[key]);
        } else if (typeof obj[key] === 'object') {
          escapeObject(obj[key]);
        }
      });
    }
    return obj;
  };

  req.query = escapeObject(req.query);
  req.body = escapeObject(req.body);

  next();
};

module.exports = {
  commonValidators,
  handleValidationErrors,
  sanitizeInput,
  preventXSS,
};

