// Security audit script to check for common vulnerabilities
const fs = require('fs');
const path = require('path');

console.log('🔒 Security Audit Report\n');

const checks = [
  {
    name: 'Environment Files',
    check: () => {
      const envFiles = ['.env', '.env.local', '.env.production'];
      const found = envFiles.filter(file => fs.existsSync(file));

      if (found.length > 0) {
        return {
          status: 'WARNING',
          message: `Found environment files: ${found.join(', ')}. Ensure these are NOT committed to version control.`
        };
      }
      return { status: 'OK', message: 'No environment files found in repo' };
    }
  },
  {
    name: 'Package.json Dependencies',
    check: () => {
      try {
        const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));
        const insecureDeps = [
          'express', 'body-parser', 'mongoose', 'lodash', 'moment', 'request'
        ].filter(dep => packageJson.dependencies && packageJson.dependencies[dep]);

        if (insecureDeps.length > 0) {
          return {
            status: 'WARNING',
            message: `Potentially vulnerable dependencies: ${insecureDeps.join(', ')}. Run npm audit regularly.`
          };
        }
        return { status: 'OK', message: 'No known vulnerable dependencies detected' };
      } catch {
        return { status: 'INFO', message: 'No package.json found' };
      }
    }
  },
  {
    name: 'Hardcoded Secrets',
    check: () => {
      const files = fs.readdirSync('.').filter(file => file.endsWith('.js'));
      const secretPatterns = [
        /password\s*[:=]\s*['"][^'"']+['"]/gi,
        /api[_-]?key\s*[:=]\s*['"][^'"']+['"]/gi,
        /secret\s*[:=]\s*['"][^'"']+['"]/gi,
        /token\s*[:=]\s*['"][^'"']+['"]/gi
      ];

      let findings = [];

      files.forEach(file => {
        const content = fs.readFileSync(file, 'utf8');
        secretPatterns.forEach(pattern => {
          const matches = content.match(pattern);
          if (matches) {
            findings.push(`${file}: ${matches[0]}`);
          }
        });
      });

      if (findings.length > 0) {
        return {
          status: 'CRITICAL',
          message: `Hardcoded secrets found:\n${findings.join('\n')}`
        };
      }
      return { status: 'OK', message: 'No hardcoded secrets found' };
    }
  }
];

// Run all checks
checks.forEach(check => {
  const result = check.check();
  console.log(`[${result.status}] ${check.name}: ${result.message}\n`);
});

console.log('✅ Security audit completed. Review findings above.');

