// Environment variable validation for security
const Joi = require('joi');

// Schema for validating environment variables
const envSchema = Joi.object({
  // Server configuration
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().port().default(3000),

  // Security configuration
  RATE_LIMIT_MAX: Joi.number().integer().min(1).max(1000).default(100),
  ALLOWED_ORIGINS: Joi.string().optional(),
  SESSION_SECRET: Joi.string().min(32).required().when('NODE_ENV', {
    is: 'production',
    then: Joi.required()
  }),

  // Database configuration (optional for this simple app, but validated if present)
  DATABASE_URL: Joi.string().uri().optional(),

  // API keys (optional for this simple app, but validated if present)
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),
  LOGFIRE_TOKEN: Joi.string().optional()
}).unknown(true); // Allow other env vars but don't validate them

// Validate environment variables
function validateEnv() {
  const { error, value } = envSchema.validate(process.env, { allowUnknown: true });

  if (error) {
    throw new Error(`Environment validation error: ${error.message}`);
  }

  return value;
}

// Security check for sensitive environment variables
function checkSensitiveEnvVars() {
  const sensitiveVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID', 
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
    'SESSION_SECRET'
  ];

  const warnings = [];

  sensitiveVars.forEach(varName => {
    if (process.env[varName] && process.env.NODE_ENV === 'production') {
      // Check for common insecure patterns in production
      if (process.env[varName].includes('CANARY') || 
          process.env[varName].includes('test') ||
          process.env[varName].includes('example')) {
        warnings.push(`WARNING: ${varName} appears to contain test/placeholder value in production`);
      }
    }
  });

  return warnings;
}

module.exports = {
  validateEnv,
  checkSensitiveEnvVars,
  envSchema
};

// Secure Express.js application with proper environment validation and error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validateEnv, checkSensitiveEnvVars } = require('./config/env-validation');

// Validate environment variables before starting
console.log('🔒 Validating environment configuration...');
try {
  validateEnv();

  // Check for potential security issues with sensitive env vars
  const warnings = checkSensitiveEnvVars();
  if (warnings.length > 0) {
    console.warn('⚠️  Environment variable warnings:');
    warnings.forEach(warning => console.warn(`   ${warning}`));
  }

  console.log('✅ Environment validation passed');
} catch (error) {
  console.error('❌ Environment validation failed:', error.message);
  process.exit(1);
}

const app = express();

// Security Middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' }));

// Rate limiting based on environment configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: process.env.RATE_LIMIT_MAX || 100,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health endpoint with error handling
app.get('/health', (req, res, next) => {
  try {
    // Validate any query parameters if needed
    if (req.query.detailed && req.query.detailed !== 'true') {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'detailed parameter must be "true" if provided' 
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV,
      uptime: process.uptime()
    };

    if (req.query.detailed === 'true') {
      response.memory = process.memoryUsage();
      response.versions = process.versions;
    }

    res.json(response);
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Input validation for query parameters
    const { page, limit, search } = req.query;

    if (page && !/^\d+$/.test(page)) {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'page must be a positive integer' 
      });
    }

    if (limit && (!/^\d+$/.test(limit) || parseInt(limit) > 100)) {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'limit must be a positive integer not exceeding 100' 
      });
    }

    if (search && search.length > 100) {
      return res.status(400).json({ 
        error: 'Invalid parameter', 
        message: 'search query too long (max 100 characters)' 
      });
    }

    // Mock user data - sanitized output
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply basic filtering (sanitized)
    let filteredUsers = [...users];
    if (search) {
      const searchTerm = search.toLowerCase().trim();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    res.json(filteredUsers);
  } catch (error) {
    next(error);
  }
});

// Enhanced error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', {
    message: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose implementation details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { 
        error: error.message,
        ...(error.stack && { stack: error.stack })
      };

  res.status(error.status || 500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path,
    method: req.method 
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`✅ Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);

  // Security reminder
  if (process.env.NODE_ENV === 'production') {
    console.log('🔒 Production mode: Ensure all environment variables are properly secured');
  }
});

module.exports = app;

