// Example of secure environment configuration and validation
// This demonstrates best practices for handling credentials safely

const Joi = require('joi');

// Environment variable validation schema
const envSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),

  PORT: Joi.number()
    .port()
    .default(3000),

  // Database configuration validation
  DATABASE_URL: Joi.string()
    .uri({ scheme: ['postgres', 'postgresql'] })
    .when('NODE_ENV', { 
      is: 'production', 
      then: Joi.required(),
      otherwise: Joi.optional()
    }),

  // API key validation (format only, never validate against live services)
  AWS_ACCESS_KEY_ID: Joi.string()
    .pattern(/^AKIA[0-9A-Z]{16}$/)
    .optional(),

  AWS_SECRET_ACCESS_KEY: Joi.string()
    .min(40)
    .optional(),

  ANTHROPIC_API_KEY: Joi.string()
    .pattern(/^sk-ant-[a-zA-Z0-9_-]+$/)
    .optional(),

  STRIPE_SECRET_KEY: Joi.string()
    .pattern(/^sk_(live|test)_[a-zA-Z0-9]+$/)
    .optional(),

  LOGFIRE_TOKEN: Joi.string()
    .min(20)
    .optional()
});

// Safe validation function (never tests connectivity)
function validateEnvironment(envVars) {
  const { value, error } = envSchema.validate(envVars, { 
    abortEarly: false,
    allowUnknown: true // Allow extra env vars without validation
  });

  if (error) {
    const errorMessages = error.details.map(detail => ({
      path: detail.path.join('.'),
      message: detail.message,
      value: detail.context.value ? '***REDACTED***' : undefined
    }));

    throw new Error(`Environment validation failed: ${JSON.stringify(errorMessages, null, 2)}`);
  }

  return value;
}

// Safe credential masker for logging
function maskSensitiveValues(config) {
  const masked = { ...config };

  const sensitiveKeys = [
    'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'
  ];

  sensitiveKeys.forEach(key => {
    if (masked[key]) {
      masked[key] = '***REDACTED***';
    }
  });

  return masked;
}

// Example usage (safe validation only)
module.exports = {
  validateEnvironment,
  maskSensitiveValues,
  envSchema
};

