const { validationResult, body, query, param } = require('express-validator');

// Common validation rules
exports.validateUserQuery = [
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('search').optional().isLength({ max: 100 }).withMessage('Search term too long')
];

// Sanitization middleware
exports.sanitizeInput = (req, res, next) => {
  // Basic XSS protection
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
      }
    });
  }
  next();
};

// Validation error handler
exports.handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Default error
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    statusCode = 400;
    message = 'Validation Error';
  } else if (err.name === 'UnauthorizedError') {
    statusCode = 401;
    message = 'Unauthorized';
  } else if (err.code === 'LIMIT_FILE_SIZE') {
    statusCode = 413;
    message = 'File too large';
  }

  // Don't leak internal errors in production
  if (process.env.NODE_ENV === 'production' && statusCode === 500) {
    message = 'Internal Server Error';
  }

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Custom error classes
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message = 'Validation failed') {
    super(message, 400);
    this.name = 'ValidationError';
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
    this.name = 'NotFoundError';
  }
}

module.exports = {
  errorHandler,
  asyncHandler,
  AppError,
  ValidationError,
  NotFoundError
};

const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Security headers middleware
const securityHeaders = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false,
  crossOriginResourcePolicy: { policy: "same-site" }
});

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : ['http://localhost:3000', 'http://localhost:3001'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
};

// NoSQL injection protection
const nosqlInjectionProtection = (req, res, next) => {
  const checkForNoSQLInjection = (obj) => {
    for (const key in obj) {
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        checkForNoSQLInjection(obj[key]);
      } else if (typeof obj[key] === 'string') {
        // Check for MongoDB operator patterns
        if (obj[key].match(/^\$(eq|ne|gt|gte|lt|lte|in|nin|or|and|not|exists|type|mod|regex|text|where|all|elemMatch|size|meta|slice|comment)$/i)) {
          throw new Error('Potential NoSQL injection detected');
        }
      }
    }
  };

  try {
    if (req.body) checkForNoSQLInjection(req.body);
    if (req.query) checkForNoSQLInjection(req.query);
    if (req.params) checkForNoSQLInjection(req.params);
    next();
  } catch (error) {
    res.status(400).json({ error: 'Invalid request parameters' });
  }
};

module.exports = {
  securityHeaders,
  apiLimiter,
  corsOptions,
  nosqlInjectionProtection
};

require('dotenv').config();

const config = {
  // Server configuration
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',

  // Security
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || [],

  // Rate limiting
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 900000, // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX) || 100
  },

  // Logging
  logLevel: process.env.LOG_LEVEL || 'info',

  // Validation
  validation: {
    maxStringLength: parseInt(process.env.MAX_STRING_LENGTH) || 255,
    maxFileSize: parseInt(process.env.MAX_FILE_SIZE) || 5242880 // 5MB
  }
};

// Validate required environment variables
const requiredEnvVars = [];
if (process.env.NODE_ENV === 'production') {
  requiredEnvVars.push('ALLOWED_ORIGINS');
}

requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.warn(`Warning: Environment variable ${envVar} is required but not set`);
  }
});

module.exports = config;

// Enhanced application with comprehensive security measures
require('dotenv').config();

const express = require('express');
const cors = require('cors');
const { express: expressValidation } = require('express-validator');

// Import custom middleware
const { securityHeaders, apiLimiter, corsOptions, nosqlInjectionProtection } = require('./middleware/security');
const { errorHandler, asyncHandler } = require('./middleware/errorHandler');
const { validateUserQuery, handleValidationErrors, sanitizeInput } = require('./middleware/validation');
const config = require('./config');

const app = express();

// Security middleware - apply first
app.use(securityHeaders);
app.use(cors(corsOptions));
app.use(apiLimiter);
app.use(nosqlInjectionProtection);

// Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Input sanitization
app.use(sanitizeInput);

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.env,
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Users endpoint with validation
app.get('/users', 
  validateUserQuery,
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, search } = req.query;

    // Validate numeric parameters
    if (isNaN(parseInt(limit)) || isNaN(parseInt(offset))) {
      throw new ValidationError('Limit and offset must be valid numbers');
    }

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering if search term provided
    let filteredUsers = users;
    if (search) {
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parseInt(offset), parseInt(offset) + parseInt(limit));

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: parseInt(offset) + parseInt(limit) < filteredUsers.length
      }
    });
  })
);

// User detail endpoint with parameter validation
app.get('/users/:id', 
  [
    expressValidation.param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
    handleValidationErrors
  ],
  asyncHandler(async (req, res) => {
    const userId = parseInt(req.params.id);

    // Simulate database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new NotFoundError(`User with ID ${userId} not found`);
    }

    res.json(user);
  })
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl
  });
});

// Global error handler (must be last)
app.use(errorHandler);

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = config.port;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${config.env} mode`);
});

module.exports = app;

