const express = require('express');

const app = express();

// Basic security middleware
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Input validation middleware
app.use((req, res, next) => {
  // Basic query parameter validation
  const { limit, offset } = req.query;

  if (limit && (isNaN(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ error: 'Limit must be a number ≤ 100' });
  }

  if (offset && (isNaN(offset) || parseInt(offset) < 0)) {
    return res.status(400).json({ error: 'Offset must be a positive number' });
  }

  next();
});

// Enhanced health endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Enhanced users endpoint with validation
app.get('/users', (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Validated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply safe pagination
    const safeLimit = Math.min(parseInt(limit) || 10, 100);
    const safeOffset = Math.max(parseInt(offset) || 0, 0);

    const paginatedUsers = users.slice(safeOffset, safeOffset + safeLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit: safeLimit,
        offset: safeOffset
      }
    });

  } catch (error) {
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);
  res.status(500).json({ error: 'Internal server error' });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});

