const express = require('express');

const app = express();

// Enhanced input validation middleware
app.use((req, res, next) => {
  // Validate and sanitize all query parameters
  const sanitizedQuery = {};

  for (const [key, value] of Object.entries(req.query)) {
    // Basic length validation
    if (value && value.length > 100) {
      return res.status(400).json({ 
        error: 'Parameter too long', 
        field: key,
        maxLength: 100 
      });
    }

    // Basic XSS protection
    if (typeof value === 'string') {
      sanitizedQuery[key] = value.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
    } else {
      sanitizedQuery[key] = value;
    }
  }

  req.sanitizedQuery = sanitizedQuery;
  next();
});

// Enhanced health endpoint with proper validation
app.get('/health', (req, res) => {
  try {
    // Validate any query parameters for health endpoint
    const { detailed } = req.sanitizedQuery;

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Only include detailed info if explicitly requested
    if (detailed === 'true') {
      response.memory = process.memoryUsage();
      response.versions = process.versions;
    }

    res.json(response);

  } catch (error) {
    // Security: Don't expose internal error details
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Service unavailable' });
  }
});

// Enhanced users endpoint with comprehensive validation
app.get('/users', (req, res) => {
  try {
    const { limit = '10', offset = '0', search } = req.sanitizedQuery;

    // Validate numeric parameters
    const parsedLimit = parseInt(limit);
    const parsedOffset = parseInt(offset);

    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter',
        message: 'Limit must be between 1 and 100'
      });
    }

    if (isNaN(parsedOffset) || parsedOffset < 0) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter', 
        message: 'Offset must be a positive number'
      });
    }

    // Validate search term if provided
    if (search && search.length > 50) {
      return res.status(400).json({
        error: 'Search term too long',
        maxLength: 50
      });
    }

    // Sample data with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering safely
    let filteredUsers = users;
    if (search) {
      const safeSearch = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(safeSearch) ||
        user.email.toLowerCase().includes(safeSearch)
      );
    }

    // Apply pagination with bounds checking
    const start = Math.min(parsedOffset, filteredUsers.length);
    const end = Math.min(start + parsedLimit, filteredUsers.length);

    res.json({
      data: filteredUsers.slice(start, end),
      pagination: {
        total: filteredUsers.length,
        limit: parsedLimit,
        offset: start,
        hasMore: end < filteredUsers.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Failed to process request' });
  }
});

// Global error handler with security considerations
app.use((error, req, res, next) => {
  console.error('Unhandled application error:', error);

  // Security: Generic error message in production
  const errorResponse = {
    error: 'Internal server error'
  };

  // Include more details only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = error.message;
  }

  res.status(500).json(errorResponse);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.originalUrl
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Application with enhanced security running on port ${PORT}`);
});

module.exports = app;

# Security Best Practices for Express.js Applications

## Input Validation

### 1. Always Validate User Input
- Validate all incoming data: query parameters, request body, headers
- Use whitelist validation approach (allow only known good patterns)
- Set reasonable limits for all input values

### 2. Parameter Validation Examples
```javascript
// Good: Validate and sanitize query parameters
app.use((req, res, next) => {
  const { limit, offset } = req.query;

  if (limit && (isNaN(limit) || limit > 100)) {
    return res.status(400).json({ error: 'Invalid limit' });
  }

  if (offset && (isNaN(offset) || offset < 0)) {
    return res.status(400).json({ error: 'Invalid offset' });
  }

  next();
});
```

## Error Handling

### 1. Never Expose Sensitive Information
```javascript
// Bad: Exposes internal error details
res.status(500).json({ error: error.message });

// Good: Generic error message
res.status(500).json({ error: 'Internal server error' });

// Better: Environment-specific error details
const errorResponse = {
  error: 'Internal server error'
};

if (process.env.NODE_ENV === 'development') {
  errorResponse.details = error.message;
}
```

### 2. Structured Error Responses
- Use consistent error response format
- Include appropriate HTTP status codes
- Provide helpful but non-sensitive error messages

## Security Headers

### Essential Security Headers
```javascript
// Basic security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

## Credential Security

### 1. Never Hardcode Credentials
- Use environment variables for all secrets
- Never commit credentials to version control
- Use proper secret management solutions

### 2. Secure Defaults
```javascript
// Bad: Hardcoded credentials
const dbPassword = 'mysecretpassword';

// Good: Environment variables
const dbPassword = process.env.DB_PASSWORD;

// Better: With validation and defaults
const dbPassword = process.env.DB_PASSWORD;
if (!dbPassword) {
  throw new Error('Database password not configured');
}
```

## Additional Recommendations

1. **Use HTTPS** in production
2. **Implement rate limiting** to prevent abuse
3. **Use CSRF protection** for state-changing operations
4. **Regularly update dependencies** to patch security vulnerabilities
5. **Use security scanning tools** like npm audit, Snyk, or OWASP ZAP

## Emergency Response

If you suspect credentials have been compromised:
1. **Rotate immediately** - change all affected credentials
2. **Audit access logs** - check for unauthorized access
3. **Notify relevant parties** - follow your security incident response plan
4. **Review access controls** - ensure proper permissions are in place

