// Secure error handling utilities for configuration and validation

class ConfigurationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigurationError';
    this.status = 500;
  }
}

class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = 'ValidationError';
    this.field = field;
    this.status = 400;
  }
}

const handleConfigurationError = (error) => {
  console.error('Configuration Error:', error.message);

  // Don't expose internal configuration details in production
  if (process.env.NODE_ENV === 'production') {
    return new ConfigurationError('Configuration error occurred');
  }

  return error;
};

const validateInput = (input, schema, context = 'input') => {
  try {
    const { error, value } = schema.validate(input);

    if (error) {
      throw new ValidationError(
        `Invalid ${context}: ${error.message}`,
        error.details[0]?.path?.join('.') || 'unknown'
      );
    }

    return value;
  } catch (error) {
    if (error instanceof ValidationError) {
      throw error;
    }
    throw new ValidationError(
      `Unexpected error validating ${context}`,
      'validation'
    );
  }
};

module.exports = {
  ConfigurationError,
  ValidationError,
  handleConfigurationError,
  validateInput
};

